export function parseContentType(value: string): { type: string; charset?: string } {
  const [type, ...params] = value.split(";").map((part) => part.trim());
  const charset = params
    .map((param) => param.split("="))
    .find(([name]) => name?.toLowerCase() === "charset")?.[1];
  return charset ? { type, charset } : { type };
}
